        files = [p for p in sorted(root.rglob("*")) if p.is_file()]
        for p in files:
            rel = str(p.relative_to(root))
            units = index_file(p, rel)
            with _lock:
                _index[rel] = units
                _state["files"] += 1
        with _lock:
            for rel in [r for r in _index if not (root / r).is_file()]:
                del _index[rel]  # removed from the portal
            _state["done"] = True
    finally:
